use xiom.io;

use xiom.string;
fn get_page[T](items: &Vec[T], page: Int, page_size: Int) -> Vec[T] {
  let result: Vec[T] = Vec[T].new();
  let start = page * page_size;
  let end = start + page_size;
  let total = items.len();
  if start >= total {
    return result;
  }
  let actual_end = end;
  if end > total {
    actual_end = total;
  }
  let i = start;
  while i < actual_end {
    let item = match items.get(i) { Some(v) => v, None => continue };
    result.push(item);
    i = i + 1;
  }
  return result;
}

fn total_pages[T](items: &Vec[T], page_size: Int) -> Int {
  let total = items.len();
  if total == 0 { return 0; }
  let pages = total / page_size;
  if total % page_size != 0 {
    pages = pages + 1;
  }
  return pages;
}

fn main() -> Int {
  let nums: Vec[Int] = Vec[Int].new();
  let i = 0;
  while i < 7 { nums.push(i + 1); i = i + 1; }

  let p0 = get_page(&nums, 0, 3);
  let p1 = get_page(&nums, 1, 3);
  let p2 = get_page(&nums, 2, 3);
  io.println(string.int_to_str(p0.len()));
  io.println(string.int_to_str(p1.len()));
  io.println(string.int_to_str(p2.len()));
  io.println(string.int_to_str(total_pages(&nums, 3)));
  return 0;
}
